import{_ as t,o,c as d,a2 as a}from"./chunks/framework.BVc2lkLk.js";const m=JSON.parse('{"title":"内置插件","description":"QFlareBot 自带的 sid（查身份）与 t2i（HTML 转图片）两个插件的命令和用法。","frontmatter":{"description":"QFlareBot 自带的 sid（查身份）与 t2i（HTML 转图片）两个插件的命令和用法。"},"headers":[],"relativePath":"builtin-plugins.md","filePath":"builtin-plugins.md","lastUpdated":1790607621000}'),r={name:"builtin-plugins.md"};function i(c,e,n,l,s,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="内置插件" tabindex="-1">内置插件 <a class="header-anchor" href="#内置插件" aria-label="Permalink to &quot;内置插件&quot;">​</a></h1><p>仓库自带两个插件，写在 <code>apps/seed/qqbot.manifest.json</code> 里，部署后默认开启：<code>sid</code> 查身份，<code>t2i</code> 给别的插件提供 HTML 转图片服务。更多插件去<a href="./market">插件市场</a>装。</p><p>不想要哪个，在面板「插件」页把它关掉就行，即时生效、不触发构建。面板上卸载不了内置插件；要从部署里彻底拿掉，改 <code>qqbot.manifest.json</code> 并提交。</p><p>下面的命令都以默认前缀 <code>/</code> 为例。群里 @机器人 或单聊时可以不带前缀。</p><h2 id="sid-查身份" tabindex="-1">sid：查身份 <a class="header-anchor" href="#sid-查身份" aria-label="Permalink to &quot;sid：查身份&quot;">​</a></h2><p><code>/sid</code>（别名 <code>/id</code>）回复你在这个机器人下的 openid、当前会话 id 与场景、你在群里的角色，以及机器人的名字和 AppID。群聊和单聊里用 markdown 回复，openid 和会话 id 各放一个代码块，点复制按钮就能拿到；频道没开放 markdown，仍回纯文本。</p><p>部署完用它检查机器人能不能收发消息。面板「设置 → 权限」里配 Bot 管理员名单要填 openid，也先用它查。openid 按机器人隔离，从别处复制来的无效。</p><h2 id="t2i-html-转图片服务" tabindex="-1">t2i：HTML 转图片服务 <a class="header-anchor" href="#t2i-html-转图片服务" aria-label="Permalink to &quot;t2i：HTML 转图片服务&quot;">​</a></h2><p>没有命令。它给别的插件提供一个 <code>t2i</code> 服务：把 HTML 渲染成图片，适合做海报、排行榜这类图文消息。用法是在插件里声明 <code>depends: { t2i: &#39;*&#39; }</code>，再 <code>ctx.service(&#39;t2i&#39;)</code> 取出来调用（见<a href="./plugin-guide#要读别的插件的数据">插件开发指南 · 要读别的插件的数据</a>）。</p><p>发图用 <code>renderUrl(html)</code>：图存在渲染服务上，只回一个地址，放进 <code>{ image: { url } }</code> 让 QQ 自己去拉，图片不经过 Worker。<code>renderBase64(html)</code> 要在 Worker 里把整张图编码一遍，吃的是全机器人共享的 CPU，只在拿不到地址时用。</p><p>渲染不在 Worker 里做（CPU 不够），而是调用外部的 <a href="https://github.com/AstrBotDevs/AstrBot" target="_blank" rel="noreferrer">AstrBot T2I</a> 渲染服务：</p><table tabindex="0"><thead><tr><th>配置</th><th>说明</th></tr></thead><tbody><tr><td><code>t2i_url</code></td><td>渲染服务地址，要支持 <code>POST /text2img/generate</code>。默认是作者部署在 Hugging Face 上的公共实例，不保证可用，量大的话自己部署一个</td></tr><tr><td><code>t2i_timeout</code></td><td>渲染超时（毫秒，5000–30000，默认 25000）。上限是 30 秒，因为一次事件的全部处理只有 30 秒，再长也会被平台掐断；以前存过更大的值照旧生效，下次在面板保存时要改到 30000 以内</td></tr></tbody></table><p>面板侧栏「插件页面 → T2I 渲染服务」可以测试连通性、试渲染一段 HTML。</p><h2 id="以前的演示插件" tabindex="-1">以前的演示插件 <a class="header-anchor" href="#以前的演示插件" aria-label="Permalink to &quot;以前的演示插件&quot;">​</a></h2><p>早期版本还预装了 <code>echo</code>、<code>multi-reply</code>、<code>image</code>、<code>keyboard</code> 四个演示插件，现在已经去掉。升级后它们会在下次构建时从 Worker 上消失；<code>keyboard</code> 存过的按键点击记录会出现在面板「存储」页的「孤儿数据」里，可以在那里清掉。写插件要参考按键用法，看<a href="https://github.com/QFlareBot/QFlareBot/blob/main/templates/plugin/src/index.ts" target="_blank" rel="noreferrer">插件模板</a>。</p>',15)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
